	// Fast path.
	if strings.HasPrefix(in, "http://") || strings.HasPrefix(in, "https://") {
		return true, nil
	}
	u, err := url.Parse(in)
	if err != nil {
		return false, err
	}
	return u.IsAbs(), nil
}

func (p *PathSpec) RelURL(in string, addLanguage bool) string {
	isAbs, err := p.IsAbsURL(in)
	if err != nil {
		return in
	}
	baseURL := p.getBaseURLRoot(in)
